import React, { useState } from "react";
import { auth } from "../../firebaseConfig";
import { signInWithEmailAndPassword, sendPasswordResetEmail } from "firebase/auth";
import { Link, navigate } from "gatsby";
import { useTranslation } from "react-i18next";
import {
  Box,
  Button,
  FormControl,
  IconButton,
  InputAdornment,
  InputLabel,
  OutlinedInput,
  TextField,
  Typography,
} from "@mui/material";
import Visibility from "@mui/icons-material/Visibility";
import VisibilityOff from "@mui/icons-material/VisibilityOff";

const LoginForm: React.FC = () => {
  const { t } = useTranslation();
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });
  const [error, setError] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isForgotPassword, setIsForgotPassword] = useState(false); // Nuevo estado para alternar paneles
  const [successMessage, setSuccessMessage] = useState("");

  const textFieldStyles = {
    "& .MuiFormLabel-root": { color: "#232B22" },
    "& .MuiInputBase-input": { color: "#232B22" },
    "& .MuiOutlinedInput-notchedOutline": { borderColor: "rgba(0, 0, 0, 0.2)" },
    "&:hover .MuiOutlinedInput-notchedOutline": { borderColor: "rgba(0, 0, 0, 0.4)" },
    "&.Mui-focused .MuiOutlinedInput-notchedOutline": { borderColor: "#232B22" },
  };

  const handleLogin = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    setError("");

    try {
      const userCredential = await signInWithEmailAndPassword(
        auth,
        formData.email,
        formData.password
      );
      navigate("/admin");
    } catch (error: any) {
      setError(
        error.message || t("login.errors.invalidCredentials") || "Invalid credentials."
      );
    }
  };

  const handleForgotPassword = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    setError("");
    setSuccessMessage("");

    try {
      await sendPasswordResetEmail(auth, formData.email);
      setSuccessMessage(
        t("login.success.resetEmailSent") ||
          "Password reset email sent. Check your inbox."
      );
    } catch (error: any) {
      setError(
        error.message || t("login.errors.resetFailed") || "Failed to send reset email."
      );
    }
  };

  const handleInputChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  const handleClickShowPassword = () => setShowPassword((show) => !show);

  const handleMouseDownPassword = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
  };

  const handleMouseUpPassword = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
  };

  return (
    <Box
      component="form"
      sx={{ "& > :not(style)": { mt: 4, width: "100%" } }}
      noValidate
      autoComplete="off"
      onSubmit={isForgotPassword ? handleForgotPassword : handleLogin}
      className={styles.container}
    >
      <Typography variant="h4" className={styles.title}>
        {isForgotPassword
          ? t("login.titles.forgot") || "Reset Password"
          : t("login.titles.login") || "Sign In"}
      </Typography>
      {error && <p className="text-Red text-xs">{error}</p>}
      {successMessage && (
        <p className="text-DarkGreen text-xs">{successMessage}</p>
      )}

      <TextField
        id="email"
        label={t("login.emailLabel") || "Email"}
        variant="outlined"
        sx={textFieldStyles}
        name="email"
        value={formData.email}
        onChange={handleInputChange}
        required
        error={!!error}
      />

      {!isForgotPassword && (
        <FormControl sx={textFieldStyles} variant="outlined">
          <InputLabel htmlFor="outlined-adornment-password">
            {t("login.passwordLabel") || "Password"}
          </InputLabel>
          <OutlinedInput
            id="outlined-adornment-password"
            type={showPassword ? "text" : "password"}
            endAdornment={
              <InputAdornment position="end">
                <IconButton
                  aria-label={
                    showPassword
                      ? t("login.aria.hidePassword") || "Hide password"
                      : t("login.aria.showPassword") || "Show password"
                  }
                  onClick={handleClickShowPassword}
                  onMouseDown={handleMouseDownPassword}
                  onMouseUp={handleMouseUpPassword}
                  edge="end"
                >
                  {showPassword ? <VisibilityOff /> : <Visibility />}
                </IconButton>
              </InputAdornment>
            }
            label="Contraseña"
            name="password"
            value={formData.password}
            onChange={handleInputChange}
            required
          />
        </FormControl>
      )}

      <Button
        type="submit"
        variant="contained"
        className="w-full border body-mob sm:body !backdrop-blur-md rounded-lg py-3 px-4 border-LightGrayText hover:border-Yellow bg-white/10 hover:bg-white/20 active:bg-Yellow active:border-LightGrayText"
        sx={{
          color: "rgba(255,255,255)",
          backgroundColor: "#232B22",
          "&:hover": { backgroundColor: "rgba(255,255,255,0.2)", color : "#232B22" },
        }}
      >
        {isForgotPassword
          ? t("login.actions.sendReset") || "Send reset link"
          : t("login.actions.signIn") || "Sign In"}
      </Button>

      <Button
        variant="text"
        onClick={() => {
          setIsForgotPassword((prev) => !prev);
          setError("");
          setSuccessMessage("");
        }}
        className="mt-2"
        sx={{ color: "#232B22" }}
      >
        {isForgotPassword
          ? t("login.actions.backToLogin") || "Back to sign in"
          : t("login.actions.forgotPassword") || "Forgot your password?"}
      </Button>

    </Box>
  );
};

const styles = {
  container:
    "p-8 rounded-lg shadow-md border border-LightGrayText w-full max-w-md mx-auto my-8",
  title: "text-2xl font-bold mb-6 text-DarkGreen text-center",
  errorMessage: "text-red-600 text-xs",
};

export default LoginForm;
